@using sv_00a2284b82ff43dba6b16ac5e446edf4

<div class="card mb-2">
    <div class="card-body p-2">
        <h6 class="card-title mb-1">@Task.Title</h6>
        <p class="card-text mb-1 text-muted small">@Task.Assignee</p>
        <span class="badge @PriorityClass me-1">@Task.Priority</span>
        <span class="text-muted small">@Task.DueDate.ToString("MMM dd")</span>
        <div class="mt-2 d-flex gap-1">
            @if (CanMoveLeft)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveLeft" disabled="@IsMoving">← Move Left</button>
            }
            @if (CanMoveRight)
            {
                <button class="btn btn-outline-secondary btn-sm" @onclick="OnMoveRight" disabled="@IsMoving">Move Right →</button>
            }
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }
    [Parameter] public bool IsMoving { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };
}

@using sv_00a2284b82ff43dba6b16ac5e446edf4

<div class="col">
    <div class="card h-100">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">@ColumnName</h5>
            <span class="badge bg-secondary">@Tasks.Count</span>
        </div>
        <div class="card-body overflow-auto" style="max-height: 60vh;">
            @foreach (var task in Tasks)
            {
                <TaskCard Task="task"
                          CanMoveLeft="CanMoveLeft"
                          CanMoveRight="CanMoveRight"
                          IsMoving="@(_movingTaskId == task.Id)"
                          OnMoveLeft="() => HandleMove(task.Id, MoveDirection.Left)"
                          OnMoveRight="() => HandleMove(task.Id, MoveDirection.Right)" />
            }

            @if (_showForm)
            {
                <AddTaskForm OnSave="HandleAdd" OnCancel="() => _showForm = false" />
            }
            else
            {
                <button class="btn btn-outline-primary btn-sm w-100 mt-2" @onclick="() => _showForm = true">+ Add Task</button>
            }
        </div>
    </div>
</div>

@code {
    public enum MoveDirection { Left, Right }

    [Parameter, EditorRequired] public string ColumnName { get; set; } = string.Empty;
    [Parameter, EditorRequired] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, MoveDirection Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool _showForm;
    private int? _movingTaskId;

    private async Task HandleMove(int taskId, MoveDirection direction)
    {
        _movingTaskId = taskId;
        try
        {
            await OnMoveTask.InvokeAsync((taskId, direction));
        }
        finally
        {
            _movingTaskId = null;
        }
    }

    private async Task HandleAdd((string Title, string Assignee, string Priority, DateTime DueDate) data)
    {
        await OnAddTask.InvokeAsync(data);
        _showForm = false;
    }
}

@page "/board"
@rendermode InteractiveServer
@using sv_00a2284b82ff43dba6b16ac5e446edf4
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (_isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="_tasks" />
    <BoardSearchBar @bind-SearchText="_searchText" />

    <div class="row g-3">
        @foreach (var column in _columns)
        {
            var colIndex = Array.IndexOf(_columns, column);
            <KanbanColumn ColumnName="@column"
                          Tasks="GetFilteredTasks(column)"
                          CanMoveLeft="colIndex > 0"
                          CanMoveRight="colIndex < _columns.Length - 1"
                          OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, colIndex)"
                          OnAddTask="data => HandleAddTask(data, column)" />
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
    private List<TaskItem> _tasks = new();
    private string _searchText = string.Empty;
    private bool _isLoading = true;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        _isLoading = true;
        _errorMessage = null;
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = _tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private async Task HandleMoveTask(int taskId, KanbanColumn.MoveDirection direction, int currentColIndex)
    {
        var newIndex = direction == KanbanColumn.MoveDirection.Left ? currentColIndex - 1 : currentColIndex + 1;
        if (newIndex < 0 || newIndex >= _columns.Length) return;

        var newStatus = _columns[newIndex];
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _tasks.First(t => t.Id == taskId);
            _tasks[_tasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
    }

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string column)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            _tasks.Add(newTask with { Status = column });
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
    }
}

