@page "/board"
@rendermode InteractiveServer
@using sv_00a2284b82ff43dba6b16ac5e446edf4
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (_isLoading)
{
    <div class="d-flex justify-content-center p-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="_tasks" />
    <BoardSearchBar @bind-SearchText="_searchText" />

    <div class="row g-3">
        @foreach (var column in _columns)
        {
            var colIndex = Array.IndexOf(_columns, column);
            <KanbanColumn ColumnName="@column"
                          Tasks="GetFilteredTasks(column)"
                          CanMoveLeft="colIndex > 0"
                          CanMoveRight="colIndex < _columns.Length - 1"
                          OnMoveTask="args => HandleMoveTask(args.TaskId, args.Direction, colIndex)"
                          OnAddTask="data => HandleAddTask(data, column)" />
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];
    private List<TaskItem> _tasks = new();
    private string _searchText = string.Empty;
    private bool _isLoading = true;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        _isLoading = true;
        _errorMessage = null;
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = _tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(_searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private async Task HandleMoveTask(int taskId, KanbanColumn.MoveDirection direction, int currentColIndex)
    {
        var newIndex = direction == KanbanColumn.MoveDirection.Left ? currentColIndex - 1 : currentColIndex + 1;
        if (newIndex < 0 || newIndex >= _columns.Length) return;

        var newStatus = _columns[newIndex];
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _tasks.First(t => t.Id == taskId);
            _tasks[_tasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
    }

    private async Task HandleAddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string column)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
            _tasks.Add(newTask with { Status = column });
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
    }
}

